-- Global lab test master table (platform-managed, no tenant_id)
CREATE TABLE IF NOT EXISTS lab_tests_master (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name            TEXT NOT NULL,
  code            TEXT,
  category        TEXT NOT NULL DEFAULT 'General',
  sample_type     TEXT,
  unit            TEXT,
  ref_low         NUMERIC,
  ref_high        NUMERIC,
  reference_range TEXT,
  is_active       BOOLEAN NOT NULL DEFAULT true,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE lab_tests_master ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "lab_master_read" ON lab_tests_master;
CREATE POLICY "lab_master_read" ON lab_tests_master FOR SELECT USING (auth.role() = 'authenticated');

ALTER TABLE lab_tests_catalog ADD COLUMN IF NOT EXISTS lab_master_id UUID REFERENCES lab_tests_master(id) ON DELETE SET NULL;
ALTER TABLE lab_tests_catalog ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT 'General';
CREATE INDEX IF NOT EXISTS idx_lab_catalog_master ON lab_tests_catalog(lab_master_id) WHERE lab_master_id IS NOT NULL;

